const root=document.documentElement,media=matchMedia('(prefers-reduced-motion: reduce)'),fine=matchMedia('(pointer: fine)');
const enabled=()=>!media.matches&&!document.body.classList.contains('effects-off');
function depth(el){if(el.dataset.depthReady)return;el.dataset.depthReady='1';el.classList.add('depth-card');let queued=false,pending=null;el.addEventListener('pointermove',e=>{if(!fine.matches||!enabled())return;pending={x:e.clientX,y:e.clientY};if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;const r=el.getBoundingClientRect(),x=Math.max(0,Math.min(1,(pending.x-r.left)/r.width)),y=Math.max(0,Math.min(1,(pending.y-r.top)/r.height));el.style.setProperty('--tilt-x',((.5-y)*5)+'deg');el.style.setProperty('--tilt-y',((x-.5)*7)+'deg');el.style.setProperty('--light-x',(x*100)+'%');el.style.setProperty('--light-y',(y*100)+'%');el.style.setProperty('--parallax-x',((x-.5)*-9)+'px');el.style.setProperty('--parallax-y',((y-.5)*-7)+'px');el.classList.add('depth-active');});});el.addEventListener('pointerleave',()=>{el.style.setProperty('--tilt-x','0deg');el.style.setProperty('--tilt-y','0deg');el.style.setProperty('--parallax-x','0px');el.style.setProperty('--parallax-y','0px');el.classList.remove('depth-active');});el.addEventListener('pointerdown',()=>{if(!fine.matches&&enabled())el.animate([{transform:'perspective(1000px) rotateX(0)'},{transform:'perspective(1000px) rotateX(2deg)'},{transform:'perspective(1000px) rotateX(0)'}],{duration:350});});}
function bind(){document.querySelectorAll('.car,.place,.hero-stage,.brand-story>img').forEach(depth);}bind();new MutationObserver(bind).observe(document.querySelector('#cars'),{childList:true});
document.addEventListener('click',e=>{const el=e.target.closest('button,.button,.header-button,.bottom-book,.partner-visit');if(!el||!enabled())return;const r=el.getBoundingClientRect(),ripple=document.createElement('span');ripple.className='press-ripple';ripple.style.left=(e.clientX-r.left)+'px';ripple.style.top=(e.clientY-r.top)+'px';el.classList.add('has-ripple');el.append(ripple);ripple.addEventListener('animationend',()=>ripple.remove());});
document.addEventListener('load',e=>{if(e.target.matches?.('.gallery-photo')&&enabled())e.target.animate([{opacity:.4,transform:'translateX(10px)'},{opacity:1,transform:'translateX(0)'}],{duration:320,easing:'ease-out'});},true);
const progress=document.createElement('span');progress.className='reading-progress';progress.setAttribute('aria-hidden','true');document.querySelector('#site-header').append(progress);let ticking=false;function scrollFx(){const distance=root.scrollHeight-innerHeight,ratio=distance>0?Math.max(0,Math.min(1,scrollY/distance)):0;progress.style.width=(ratio*100)+'%';ticking=false;}addEventListener('scroll',()=>{if(!ticking){ticking=true;requestAnimationFrame(scrollFx);}},{passive:true});addEventListener('resize',scrollFx);scrollFx();
if('IntersectionObserver'in window){const reveal=new IntersectionObserver(entries=>entries.forEach(e=>{if(!e.isIntersecting)return;if(enabled())e.target.animate([{opacity:.4,transform:'translateY(18px)'},{opacity:1,transform:'translateY(0)'}],{duration:650,easing:'cubic-bezier(.2,.7,.2,1)'});reveal.unobserve(e.target);}),{threshold:.08});document.querySelectorAll('.section-heading,.tips article,.partner-card,.delivery-summary').forEach(el=>reveal.observe(el));const nav=new IntersectionObserver(entries=>entries.forEach(e=>{if(!e.isIntersecting)return;document.querySelectorAll('#site-header nav a,.bottom-panel a[href^="#"]').forEach(a=>{const active=a.hash==='#'+e.target.id;a.classList.toggle('nav-active',active);if(active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});}),{rootMargin:'-20% 0px -60% 0px',threshold:0});document.querySelectorAll('main section[id]').forEach(e=>nav.observe(e));}
const atmosphere=document.createElement('div');atmosphere.className='hero-atmosphere';atmosphere.setAttribute('aria-hidden','true');atmosphere.innerHTML=Array.from({length:8},(_,i)=>`<i style="left:${8+i*11}%;top:${12+(i*17)%70}%;animation-delay:-${i*2}s;animation-duration:${13+i}s"></i>`).join('');document.querySelector('.hero').append(atmosphere);
